package com.badrulamin.University_Management.controller;  import com.badrulamin.University_Management.entity.AdmissionCandidate; import com.badrulamin.University_Management.service.AdmissionCandidateService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.ResponseEntity; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;  import com.badrulamin.University_Management.payload.response.PagedResponse; import org.springframework.data.domain.Page; import org.springframework.data.domain.PageRequest; import org.springframework.data.domain.Pageable; import org.springframework.data.domain.Sort; import org.springframework.web.bind.annotation.RequestParam;  import java.util.List;  @RestController @RequestMapping("/api/admission-candidates") @RequiredArgsConstructor public class AdmissionCandidateController {      private final AdmissionCandidateService admissionCandidateService;      @PreAuthorize("hasAuthority('ADMISSION_VIEW')")     @GetMapping     public ResponseEntity<PagedResponse<AdmissionCandidate>> findAll(             @RequestParam(defaultValue = "0") int page,             @RequestParam(defaultValue = "20") int size,             @RequestParam(defaultValue = "id") String sortBy,             @RequestParam(defaultValue = "asc") String sortDir) {         Sort sort = sortDir.equalsIgnoreCase("desc") ? Sort.by(sortBy).descending() : Sort.by(sortBy).ascending();         Pageable pageable = PageRequest.of(page, size, sort);         Page<AdmissionCandidate> paged = admissionCandidateService.findAll(pageable);         PagedResponse<AdmissionCandidate> response = new PagedResponse<>(paged.getContent(), paged.getNumber(), paged.getSize(), paged.getTotalElements(), paged.getTotalPages(), paged.isFirst(), paged.isLast());         return ResponseEntity.ok(response);     }      @GetMapping("/{id}")     @PreAuthorize("hasAuthority('ADMISSION_VIEW')")     public ResponseEntity<AdmissionCandidate> findById(@PathVariable Long id) {         return ResponseEntity.ok(admissionCandidateService.findById(id));     }      @PostMapping     @PreAuthorize("hasAuthority('ADMISSION_MANAGE')")     public ResponseEntity<AdmissionCandidate> save(@Valid @RequestBody AdmissionCandidate admissionCandidate) {         return ResponseEntity.ok(admissionCandidateService.save(admissionCandidate));     }      @PutMapping("/{id}")     @PreAuthorize("hasAuthority('ADMISSION_MANAGE')")     public ResponseEntity<AdmissionCandidate> update(@PathVariable Long id, @Valid @RequestBody AdmissionCandidate admissionCandidate) {         return ResponseEntity.ok(admissionCandidateService.update(id, admissionCandidate));     }      @DeleteMapping("/{id}")     @PreAuthorize("hasAuthority('ADMISSION_MANAGE')")     public ResponseEntity<Void> delete(@PathVariable Long id) {         admissionCandidateService.delete(id);         return ResponseEntity.noContent().build();     } }